/* gen-exceptions16: crdist-exceptions16.h, every binary16 and bfloat16
   input at which a function's fast path (crdist-fast.h) with the format's
   rounding test (crdist-round16.h) can't decide the result, with the
   correctly rounded result from MPFR (crdist-ref.c, kit_ref1). All 2^16
   inputs of each function and format are tried (2026-10-13).
     make crdist-exceptions16 */
#include <fenv.h>
#include <stdio.h>
#include <stdlib.h>
#include "kit.h"
#include "crdist-fast.h"
#include "crdist-ref.h"
#include "crdist-round16.h"

static const kit_mpfr1 REF[CRDIST_NFN] = {crdist_mpfr_erfinv, crdist_mpfr_erfcinv, crdist_mpfr_probit, crdist_mpfr_ndtr,
                                             crdist_mpfr_log_ndtr, crdist_mpfr_normpdf, crdist_mpfr_logit};
static const kit_fmt KF[CRDIST16_NFMT] = {KIT_B16, KIT_BF16};

int main(void)
{
  fesetenv(FE_DFL_ENV);
  printf("/* crdist-exceptions16.h: generated by dist/gen-exceptions16.c (make crdist-exceptions16); do not edit.\n"
         "   Every binary16 and bfloat16 input at which a fast path in crdist-fast.h, with the\n"
         "   format's rounding test (crdist-round16.h), can't decide the result, with the\n"
         "   correctly rounded result (MPFR), sorted by input bits. */\n#include <stddef.h>\n#include <stdint.h>\n");
  for (int fmt = 0; fmt < CRDIST16_NFMT; fmt++)
    for (int f = 0; f < CRDIST_NFN; f++) {
      printf("static const uint16_t crdist_exc16_%s_%s[][2] = {", crdist16_fmt_name[fmt], crdist_fn_name[f]);
      size_t n = 0, tried = 0;
      for (uint32_t u = 0; u < 65536; u++) {
        double x = crdist16_decode(fmt, (uint16_t)u), y;
        float s;
        if (crdist_special(f, (float)x, &s)) continue;
        tried++;
        if (crdist16_decide(fmt, f, x, &y)) continue;
        uint16_t want = (uint16_t)kit_ref1(KF[fmt], REF[f], u, MPFR_RNDN);
        printf("%s{0x%04x, 0x%04x}", !n ? "\n  " : n % 6 ? ", " : ",\n  ", u, want);
        n++;
      }
      printf("%s};\n#define CRDIST_EXC16_N_%s_%s %zu\n", n ? "\n" : "{0, 0}", crdist16_fmt_name[fmt], crdist_fn_name[f], n);
      fprintf(stderr, "%-5s %-8s %zu of the %zu inputs tried undecided by the fast path\n", crdist16_fmt_name[fmt], crdist_fn_name[f], n, tried);
    }
  printf("static const struct { const uint16_t (*t)[2]; size_t n; } crdist_exc16[2][%d] = {\n", CRDIST_NFN);
  for (int fmt = 0; fmt < CRDIST16_NFMT; fmt++) {
    printf("  {");
    for (int f = 0; f < CRDIST_NFN; f++)
      printf("%s{crdist_exc16_%s_%s, CRDIST_EXC16_N_%s_%s}", f ? ", " : "", crdist16_fmt_name[fmt], crdist_fn_name[f], crdist16_fmt_name[fmt], crdist_fn_name[f]);
    printf("}%s\n", fmt ? "" : ",");
  }
  printf("};\n");
  return 0;
}
